entries[32439] = { ["name"] = "Muster: Gamaschen der Seelenwache", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (375)\nBenötigt Die Todeshörigen\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung von Gamaschen der Seelenwache.\nVerkaufspreis:\nGamaschen der Seelenwache\nWird beim Anlegen gebunden\nBeine Stoff\n191 Rüstung\n+54 Ausdauer\n+72 Schattenwiderstand\nHaltbarkeit 75 / 75\nBenötigt Stufe 70\nVerkaufspreis:\nBenötigt Herz der Dunkelheit (3), Kristall der Leere , Urleben (4), Urschatten (6), Magieerfüllter Netherstoffballen (2)" }
