entries[32736] = { ["name"] = "Pläne: Flinkstahlarmschienen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (375)\nBenutzen: Lehrt Euch die Herstellung von Flinkstahlarmschienen.\nVerkaufspreis:\nFlinkstahlarmschienen\nWird beim Anlegen gebunden\nHandgelenke Platte\n772 Rüstung\n+35 Stärke\n+32 Ausdauer\nHaltbarkeit 55 / 55\nBenötigt Stufe 70\nAnlegen: Erhöht die Tempowertung um 27.\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (14), Gehärteter Adamantitbarren (2), Urluft (6), Herz der Dunkelheit (4)" }
entries[32737] = { ["name"] = "Pläne: Flinkstahlschultern", ["text"] = "Benötigt Schmiedekunst (375)\nBenutzen: Lehrt Euch die Herstellung von Flinkstahlschultern.\nVerkaufspreis:\nFlinkstahlschultern\nWird beim Aufheben gebunden\nSchulter Platte\n1324 Rüstung\n+47 Stärke\n+29 Ausdauer\nHaltbarkeit 100 / 100\nBenötigt Stufe 70\nAnlegen: Erhöht die Trefferwertung um 19.\nAnlegen: Erhöht die Tempowertung um 35.\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (18), Gehärteter Adamantitbarren (2), Urluft (8), Herz der Dunkelheit (2)" }
entries[32738] = { ["name"] = "Pläne: Morgenstahlarmschienen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (375)\nBenutzen: Lehrt Euch die Herstellung von Morgenstahlarmschienen.\nVerkaufspreis:\nMorgenstahlarmschienen\nWird beim Anlegen gebunden\nHandgelenke Platte\n772 Rüstung\n+21 Ausdauer\n+23 Intelligenz\nHaltbarkeit 55 / 55\nBenötigt Stufe 70\nAnlegen: Erhöht die Zaubertempowertung um 28.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 64 und den verursachten Schaden um bis zu 22.\nVerkaufspreis:\nBenötigt Khoriumbarren (14), Gehärteter Adamantitbarren (2), Urfeuer (6), Herz der Dunkelheit (4)" }
entries[32739] = { ["name"] = "Pläne: Morgenstahlschultern", ["text"] = "Benötigt Schmiedekunst (375)\nBenutzen: Lehrt Euch die Herstellung von Morgenstahlschultern.\nVerkaufspreis:\nMorgenstahlschultern\nWird beim Aufheben gebunden\nSchulter Platte\n1324 Rüstung\n+31 Ausdauer\n+28 Intelligenz\nHaltbarkeit 100 / 100\nBenötigt Stufe 70\nAnlegen: Erhöht die Zaubertempowertung um 38.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 81 und den verursachten Schaden um bis zu 27.\nVerkaufspreis:\nBenötigt Khoriumbarren (18), Gehärteter Adamantitbarren (2), Urfeuer (8), Herz der Dunkelheit (2)" }
