entries[32756] = { ["name"] = "Gyrobalancierter Khoriumzerstörer", ["text"] = "Wird beim Anlegen gebunden\nDistanz Schusswaffe\n148 - 275 Schaden Tempo 2.80\n(75.54 Schaden pro Sekunde)\n+27 Ausdauer\n\nGelber Sockel\nSockelbonus: +3 Ausdauer\n\nHaltbarkeit 90 / 90\nBenötigt Stufe 70\nVerkaufspreis:" }
entries[32757] = { ["name"] = "Gesegnetes Medaillon von Karabor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nHals\n+49 Ausdauer\n+40 Schattenwiderstand\nBenutzen: Teleportiert den Träger an die Stufen von Illidans Festung. (15 Min Abklingzeit)\n\"Dieser Gegenstand, einst von einem Kleriker von Karabor getragen, gewährt dem Träger Einlass in den Schwarzen Tempel.\"" }
entries[32758] = { ["name"] = "Eau de Schläger", ["text"] = "Benutzen: Schüttet es über Euren gesamten Körper, um wie ein kultivierter Oger zu riechen. Sämtliche Wesen werden Euch sicherlich schon von weitem bemerken.\n\nNur im Schergrat anwendbar.\n\"Ein erlesener Duft für den anspruchsvollen Oger.\"\nVerkaufspreis:" }
entries[32759] = { ["name"] = "Beschleunigermodul", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Wird benutzt, um die Steuerungen für Protonenbeschleunigung am Landeplatz von Bash'ir zu aktivieren.\"\nVerkaufspreis:" }
entries[32760] = { ["name"] = "Pfeil des Machognoms", ["text"] = "Wird beim Aufheben gebunden\nMunition Pfeil\nVerursacht 53 zusätzlichen Schaden pro Sekunde.\nBenötigt Stufe 70\n\"Befiedert von Andy \"Der Machognom\" Savage.\"\nVerkaufspreis:" }
entries[32761] = { ["name"] = "Die Offizierskugel", ["text"] = "Wird beim Aufheben gebunden\nMunition Kugel\nVerursacht 53 zusätzlichen Schaden pro Sekunde.\nBenötigt Stufe 70\n\"Mächtiges Badabumm.\"\nVerkaufspreis:" }
entries[32762] = { ["name"] = "Rulksters Hirnsaft", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 1800 bis 3000 Mana wieder her. (2 Min Abklingzeit)\n\"Sei kein Dummkopf, trink deinen Hirnsaft!\"\nVerkaufspreis:" }
entries[32763] = { ["name"] = "Rulksters Geheimsoße", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 1500 bis 2500 Gesundheit wieder her. (2 Min Abklingzeit)\n\"Trinkt und lebt.\"\nVerkaufspreis:" }
entries[32764] = { ["name"] = "Flaschataurens himmlisches Gebräu", ["text"] = "Benötigt Stufe 65\nBenutzen: Erhöht 2 Stunden lang die maximale Gesundheit um 500 und die Verteidigungswertung um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Der Effekt hält auch nach dem Tode an. (3 Sek. Abklingzeit)\n\"Die flaschenhafte Essenz des mythenumrankten Wesens!\"\nVerkaufspreis:" }
entries[32765] = { ["name"] = "Flaschataurens Tränen", ["text"] = "Benötigt Stufe 65\nBenutzen: Erhöht die Angriffskraft 2 Stunden lang um 120. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Der Effekt hält auch nach dem Tode an. (3 Sek. Abklingzeit)\n\"Die destillierten Tränen des schwer zu fassenden Flaschatauren.\"\nVerkaufspreis:" }
entries[32766] = { ["name"] = "Flaschataurens Fläschchen der Flaschität", ["text"] = "Benötigt Stufe 65\nBenutzen: Erhöht die Manaregeneration 2 Stunden lang um 25 Mana alle 5 Sekunden. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Der Effekt hält auch nach dem Tode an. (3 Sek. Abklingzeit)\n\"Trägt das Zeichen des Flaschatauren.\"\nVerkaufspreis:" }
entries[32767] = { ["name"] = "Flaschataurens Fläschchen der ziemlich beeindruckenden Macht", ["text"] = "Benötigt Stufe 50\nBenutzen: Erhöht die Schadenswirkung von Zaubern und magischen Effekten 2 Stunden lang um bis zu 70. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n\"Nicht überragend, aber auch nicht so schlecht.\"\nVerkaufspreis:" }
