entries[32897] = { ["name"] = "Mal der Illidari", ["text"] = "\"Trägt das Mal der Illidari. Dieser Gegenstand kann bei der Bank der Seher oder der Aldor in Shattrath eingetauscht werden.\"" }
entries[32898] = { ["name"] = "Fläschchen der Stärkung von Shattrath", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\nBenutzen: Erhöht die maximale Gesundheit 2 Stunden lang um 500 und die Verteidigungswertung um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)" }
entries[32899] = { ["name"] = "Fläschchen der mächtigen Wiederherstellung von Shattrath", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\nBenutzen: Erhöht die Manaregeneration 2 Stunden lang um 25 Mana alle 5 Sekunden. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)" }
