entries[32902] = { ["name"] = "Flasche mit Nethergonenergie", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 1800 bis 3000 Mana wieder her.\n\nWirkt nur in der Festung der Stürme: das Auge, die Arkatraz, die Botanika, die Mechanar. (2 Min Abklingzeit)\n\"In den nächstgelegenen Energieanschluss einspeisen.\"" }
