entries[33020] = { ["name"] = "Gefüllter blauer Braufestkrug", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig\n3 - 11 Schaden Tempo 2.50\n(2.80 Schaden pro Sekunde)\nBenutzen: Eine Probe Kleiner Schwips. (5 Sek. Abklingzeit)\n\"Brauerei Drohn, immer eine gute Wahl.\"" }
entries[33021] = { ["name"] = "Gefüllter blauer Braufestkrug", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig\n3 - 11 Schaden Tempo 2.50\n(2.80 Schaden pro Sekunde)\nBenutzen: Eine Probe Dschungeltropfen. (5 Sek. Abklingzeit)\n\"T'chalis Voodoobräu - So magisch, das wollt Ihr gar nicht verstehen!\"" }
