entries[33037] = { ["name"] = "Befehle der Defias", ["text"] = "Questgegenstand\n\"Diese Befehle wurden in kunstvoller Schrift auf edlem Schreibpapier verfasst.\"\n<Zum Lesen rechtsklicken>" }
entries[33038] = { ["name"] = "Beschädigte Tauchausrüstung", ["text"] = "Questgegenstand\n\"Diese Tauchausrüstung würde mit Sicherheit jeden töten, der versuchen würde, sie in ihrem jetzigen Zustand zu benutzen.\"" }
entries[33039] = { ["name"] = "Werkzeugsatz", ["text"] = "Questgegenstand\n\"Schmutziges, rostiges Werkzeug, das man nur aus purer Verzweiflung benutzen würde.\"" }
entries[33040] = { ["name"] = "Reparierte Tauchausrüstung", ["text"] = "Questgegenstand\nEinzigartig\nDauer: 1 Stunde (Realzeit)Kopf\nAnlegen: Erlaubt dem Träger, unter Wasser zu atmen.\n\"Renn hat die Ausrüstung repariert, aber wer weiß, wie lange das Ganze noch funktionstüchtig sein wird.\"" }
entries[33041] = { ["name"] = "Geborgene Geldkassette", ["text"] = "Questgegenstand\n\"Der Inhalt dieser Kassette scheint den Absturz überstanden zu haben.\"" }
entries[33042] = { ["name"] = "Schwarzer Kaffee", ["text"] = "Benötigt Stufe 65\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 7200 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Auf der Seite steht eine Warnung: Achtung HEISS! Nicht auf sich selbst oder andere schütten.\"\nVerkaufspreis:" }
entries[33043] = { ["name"] = "Die einzig wahre Braufestbrezel", ["text"] = "Dauer: 2 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 18 Sek. 61.2 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 2 Ausdauer und Willenskraft." }
entries[33044] = { ["name"] = "Bergungsausrüstung", ["text"] = "Questgegenstand\nBenutzen: Versucht, die Ladung aus den nahegelegenen Zeppelintrümmern zu bergen. (10 Sek. Abklingzeit)" }
entries[33045] = { ["name"] = "Renns Ausrüstung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Enthält eine Tauchausrüstung und Bergungsmaterial.\"\n<Zum Öffnen rechtsklicken>" }
