entries[33081] = { ["name"] = "Voodooschädel", ["text"] = "Benutzen: Werft den Schädel einem freundlich gesinnten Spieler zu. Falls er Platz in seinem Rucksack hat, wird er ihn fangen!\nVerkaufspreis:" }
