entries[33088] = { ["name"] = "Broggs Totem", ["text"] = "Questgegenstand\nBenutzen: Entfesselt die Magie von Broggs Totem über dem Leichnam eines Aschenschweifs der Feuermähnen, Spähers der Feuermähnen oder einer Bannschuppe der Feuermähnen. (5 Sek. Abklingzeit)" }
