entries[33096] = { ["name"] = "Freibierkrug des Braufests", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig\nDauer: 15 min (Realzeit)\nBenutzen: Trinkt das Gebräu und werft den Krug!\n\"Freibier in einem spaßigen Krug zum Werfen!\"" }
